// === Tab: mySketch.js ===
// It is a 3D shader made for the weekly Creative Coding Challenge
// (https://openprocessing.org/curation/78544) on the theme "Jump Scare".
// Not much to say. Just watch and enjoy the show.

let theShader;

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2425600/files/vert.glsl', 'frag.glsl');
}

function setup() {
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  createCanvas(windowWidth, windowHeight, WEBGL);
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}

// Customization for WebGL2 canvas context
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL);
			gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};


// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; in vec2 aTexCoord; out vec2 vTexCoord;
void main() { vTexCoord = aTexCoord; vec4 positionVec4 = vec4(aPosition, 1.0);  
positionVec4.xy = positionVec4.xy * 2.0 - 1.0; gl_Position = positionVec4; }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;
#define FC gl_FragCoord.xy
#define R resolution
#define T (mod(time,30.5)+13.)
#define S smoothstep
#define N normalize
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
float box(vec3 p, vec3 s, float r) {
	p=abs(p)-s;
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z))-r;
}
float map(vec3 p) {
	float plane = p.y+1.045;
	const float n = 5.;
	p.xz -= n*clamp(floor(p.xz/n+.5)*n, -1., 1.);
	vec3 q = p;
	float f = sin(q.y*8.)*.005;
	q.x += f;
	q.z += f;
	return min(
		plane,
		min(
			box(q, vec3(1), .05),
			box(p-vec3(0,1,0), vec3(1.1,.125,1.1), .0125)
		)
	);
}
vec3 dir(vec2 uv, vec3 ro, vec3 t, float z) {
	vec3 up=vec3(0,1,0),
	f=N(t-ro),
	r=N(cross(up,f)),
	u=cross(f,r),
	c=f*z,
	i=c+uv.x*r+uv.y*u,
	d=N(i);
	return d;
}
vec3 cam(float t) {
	vec3 p = vec3(.95+.7*(1.+cos(T)),sin(T*.2)+1.,2.+sin(T));
	p.xz*=rot(t);
	return p;
}
// Spline setup for camera path.
// Reference: https://www.shadertoy.com/view/4s3SRN
vec3 cp[6];
void initCam() {
	cp[0] = vec3(.95,1.8,3);
	cp[1] = vec3(-2.95,1.7,4);
	cp[2] = vec3(2,1.75,-3);
	cp[3] = vec3(2,1.75,-2);
	cp[4] = vec3(2,1.7,-2);
	cp[5] = vec3(0,1.8,-3);
}
vec3 catmull(vec3 p0, vec3 p1, vec3 p2, vec3 p3, float t){
	return (((-p0 + p1*3. - p2*3. + p3)*t*t*t + (p0*2. - p1*5. + p2*4. - p3)*t*t + (-p0 + p2)*t + p1*2.)*.5);
}
vec3 camPath(float t){
	const int n = 6;
	const float k = float(n);
	t = fract(t/k)*k;
	float
	sn = floor(t),
	st = t - sn;
	if (sn==.0) return catmull(cp[n-1], cp[0], cp[1], cp[2], st);
	for(int i=1; i<n-2; i++){
		if (sn==float(i)) return catmull(cp[i-1], cp[i], cp[i+1], cp[i+2], st);
	}
	if (sn==k-2.) return catmull(cp[n-3], cp[n-2], cp[n-1], cp[0], st);
	if (sn==k-1.) return catmull(cp[n-2], cp[n-1], cp[0], cp[1], st);
	return vec3(0);
}
float occlusion(vec3 p, vec3 n, float dist) {
	return clamp(map(p+n*dist)/dist,.0, 1.);
}
float shadow(vec3 p, vec3 lp) {
	float shd=1., maxd=length(lp-p);
	vec3 l=N(lp-p);
	for (float i=1e-3; i<maxd;) {
		float d=map(p+l*i);
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd,128.*d/i);
		i+=d;
	}
	return shd;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
vec3 scene1(vec2 uv) {
	initCam();
	float speed=T*.2;
	vec3 col = vec3(0),
	p = camPath(-speed+.5),
	tg = camPath(-speed),
	rd = dir(uv,p,tg,1.2);
	for (float i=.0; i<400.; i++) {
		float d=map(p);
		if (d<1e-3) break;
		if (d>10.) break;
		p+=rd*d;
	}
	vec3 n=norm(p),
	lp=camPath(-speed+.5)+vec3(0,-.1,0);
	lp.yz*=rot(S(.0,1.,sin(T)*.5+.5)*.1);
	lp.xz*=rot((S(.3,.8,sin(-T*2.)*.5+.5)-.5)*.2);
	vec3
	l=normalize(lp-p),
	tint=vec3(.7,.8,.85);
	float diff = 1.2*clamp(dot(n,l),.0,1.); diff*=diff*diff;
	float
  ldst = max(length(lp-p), 1e-3),
  attn = 1./(1.+ldst*.125+ldst*ldst*.05),
  shds = shadow(p+n*5e-2, lp),
  occ = occlusion(p,n,10.)*.8+.2;
	col += diff*occ*tint;
	col *= shds*exp(diff*shds);
	col *= attn;
	col = pow(clamp(col,.0,1.), vec3(.4545));
	return col;
}
// Adaptation of https://twitter.com/zozuar/status/1621229990267310081
// More variations: https://codepen.io/atzedent/full/GRXKxVL
vec3 mollusc(vec2 uv) {
	uv*=2.;
	vec2 n=vec2(0), q=vec2(0);
	float
	d=dot(uv,uv),
	s=9.,
	a=.05,
	b=sin(T*4.-d*3.)*.9,
	t=T*4.;
	uv.yx-=T*.1;
	mat2 m=mat2(-.6,.8,-.8,-.6)*.9;
	for (float i=.0; i<30.; i++) {
		uv*=m;
		n*=m;
		q=uv*s-t+b+i+n;
		a+=dot(cos(q)/s,vec2(.2));
		n-=sin(q);
		s*=1.2;
	}
	vec3 col=vec3(4,2,1)*(a+.15)+a-d;
	return sqrt(col);
}
void main(void) {
	vec2 uv = (FC-.5*R)/MN;
	vec3 col = vec3(0);
	float proc=T-13.,
	scene=floor(proc);
	if (scene < 30.) {
		col=scene1(uv); 
	} else {
		col=mix(scene1(uv),mollusc(uv),S(30.,30.2,proc));
	}
	O = vec4(col, 1);
}

